/* ===== Router & layout ===== */
const R={page:'landing',id:null,tab:null,fq:'',fv:'',excl:false,view:{},auth:'login',sf:'',flt:'all',inst:null,c1:'',c2:'',x1:'',x2:'',stab:'tampilan',rep:null};
let POST=[];
const APP=['dashboard','surveys','builder','results','distribute','settings','profile','team'];
function go(page,id,tab){if(APP.includes(page)&&!S.user){R.auth='login';page='auth'}
 if(page!=='fill'){try{if(location.hash)history.replaceState(null,'',location.pathname+location.search)}catch(e){}}
 R.page=page;R.id=id||null;R.tab=tab||null;if(page==='results'&&!tab)R.tab='ringkas';
 if(page==='results'||page==='distribute'){R.fq='';R.fv='';R.inst=null}
 closeModal();render();window.scrollTo(0,0)}
function applyPrefs(){const p=S.prefs,h=document.documentElement;
 if(p.theme==='system')h.removeAttribute('data-theme');else h.setAttribute('data-theme',p.theme);
 h.classList.toggle('big',!!p.big);h.classList.toggle('hc',!!p.hc);
 const B={maroon:['#4A0E1A','#7A1F2E','#B88C6F'],mocha:['#3A1220','#8A2B3C','#C9A27E'],anggur:['#3B0F2E','#6E1F5B','#C493A8']}[p.brand]||[];
 if(B.length){h.style.setProperty('--maroon-d',B[0]);h.style.setProperty('--maroon',B[1]);h.style.setProperty('--coksu',B[2])}
 h.style.setProperty('--font-body',`'${p.font}',system-ui,sans-serif`);
 $('#usercss').textContent=p.css||''}
const themeNext=()=>{const o=['system','light','dark'];S.prefs.theme=o[(o.indexOf(S.prefs.theme)+1)%3];save();applyPrefs();render();toast('Tema: '+{system:'ikuti perangkat',light:'terang',dark:'gelap'}[S.prefs.theme])};

function header(app){const u=S.user;
 return `<header class="top"><button class="logo" data-go="${u?'dashboard':'landing'}" aria-label="Beranda"><i>${ic('chart')}</i>${esc(S.prefs.logo)}</button>
 ${app?'':`<nav class="pubnav" aria-label="Menu utama"><button data-go="landing" data-sec="fitur">Fitur</button><button data-go="landing" data-sec="harga">Harga</button><button data-go="help">Bantuan</button><button data-go="contact">Kontak</button></nav>`}
 <span class="sp"></span>
 <button class="btn ic" data-act="theme" title="Ganti tema (terang/gelap)" aria-label="Ganti tema">${ic(S.prefs.theme==='dark'?'moon':'eye')}</button>
 ${u?`${app?'':`<button class="btn sm" data-go="dashboard">Dashboard</button>`}<button class="btn sm" data-go="profile" title="Profil">${ic('user')}<span class="pubnav" style="margin:0;display:inline">${esc(u.name.split(' ')[0])}</span></button><button class="btn ic" data-act="logout" title="Keluar" aria-label="Keluar">${ic('logout')}</button>`
 :`<button class="btn sm" data-go="auth" data-m="login">Masuk</button><button class="btn sm pri" data-go="auth" data-m="register">Daftar gratis</button>`}</header>`}
function footer(){return `<footer><span>© 2026 ${esc(S.prefs.logo)} Survey</span><span class="sp"></span><a data-go="help">Bantuan</a><a data-go="contact">Kontak</a><a data-go="legal" data-t="privasi">Kebijakan privasi</a><a data-go="legal" data-t="syarat">Syarat &amp; ketentuan</a></footer>`}
function appShell(inner,cur){const N=[['dashboard','home','Dashboard'],['surveys','list','Survei saya'],['team','users','Tim & aktivitas'],['settings','gear','Pengaturan'],['profile','user','Profil'],['help','help','Bantuan']];
 return `<div class="wrap">${header(true)}<div class="shell"><nav class="nav" aria-label="Menu aplikasi">${N.map(n=>`<button data-go="${n[0]}" class="${n[0]===cur?'on':''}" ${n[0]===cur?'aria-current="page"':''}>${ic(n[1])}${n[2]}</button>`).join('')}
 ${can()?`<button data-act="newsurvey" style="margin-top:.5rem;border:1.5px dashed var(--coksu);color:var(--link)">${ic('plus')}Survei baru</button>`:''}</nav><main class="main">${inner}</main></div>${footer()}</div>`}
const pub=inner=>`<div class="wrap">${header(false)}${inner}${footer()}</div>`;
const sel=(opts,val,attrs='')=>`<select ${attrs}>${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;
const statusPill=s=>({draft:'<span class="pill warn">Draft</span>',published:'<span class="pill ok">Aktif</span>',archived:'<span class="pill">Diarsipkan</span>'}[s.status]);

function render(){killCharts();POST=[];let h='';
 try{const f=PG[R.page];h=f?f():PG['404']()}catch(e){console.error(e);h=PG['500']()}
 const y=window.scrollY;$('#app').innerHTML=h;window.scrollTo(0,y);POST.forEach(f=>{try{f()}catch(e){console.error(e)}})}

/* ===== Halaman ===== */
const PG={};
PG.landing=()=>pub(`
<section class="hero"><div><span class="pill" style="background:rgba(255,255,255,.18);color:#fff">Untuk skripsi, riset kelas, dan evaluasi layanan</span>
<h1 style="margin-top:1rem">Tanya banyak orang, dapat jawaban yang siap dianalisis.</h1>
<p class="lead">Buat kuesioner, sebar lewat tautan atau QR, lalu lihat rata-rata, korelasi, uji validitas, dan Cronbach's Alpha tanpa membuka SPSS lebih dulu.</p>
<div class="row" style="margin-top:1.5rem"><button class="btn cta" data-go="auth" data-m="register">Mulai gratis</button><button class="btn" data-act="demofill">Coba isi survei contoh</button><button class="btn" data-act="demologin">Lihat dashboard demo</button></div></div>
<div class="mock" aria-hidden="true"><b>Saya mudah memahami cara menggunakan e-Wallet.</b><div class="scale" style="grid-template-columns:repeat(5,1fr)">${[1,2,3,4,5].map(i=>`<label class="${i===4?'on':''}" style="padding:.5rem 0"><b>${i}</b></label>`).join('')}</div><div class="bar" style="width:68%"></div><span class="small muted">Pertanyaan 4 dari 13</span>
<div class="hbar"><span class="lb">Rata-rata</span><span class="tr"><i style="width:78%"></i></span><b>3,9</b></div><div class="hbar"><span class="lb">Cronbach α</span><span class="tr"><i style="width:86%"></i></span><b>0,86</b></div></div></section>
<section class="sec" id="fitur"><h2>Dari pertanyaan sampai laporan</h2><div class="grid g3">
${[['edit','Pembuat pertanyaan','13 tipe: pilihan ganda, Likert, rating, NPS, matriks, ranking, upload, dan lainnya. Susun dengan seret dan lepas.'],['bolt','Logika alur','Lompat pertanyaan, tampilkan bersyarat, acak urutan, dan bawa jawaban sebelumnya ke pertanyaan berikutnya.'],['share','Sebar mudah','Tautan, QR code, kode sematan, kode akses, serta daftar responden dari CSV.'],['chart','Analitik langsung','Dashboard, grafik, tabel frekuensi, tabulasi silang, korelasi, dan filter segmen.'],['book','Uji instrumen','Validitas (r hitung vs r tabel) dan reliabilitas Cronbach\'s Alpha per butir.'],['shield','Privasi','Persetujuan responden, mode anonim, deteksi jawaban janggal, dan captcha.']].map(f=>`<div class="card feat"><i>${ic(f[0])}</i><h3>${f[1]}</h3><p class="muted small">${f[2]}</p></div>`).join('')}</div></section>
<section class="sec"><h2>Tiga langkah</h2><div class="grid g3">${[['Buat','Pilih tipe pertanyaan, atur logika, lalu lihat pratinjau di ponsel, tablet, dan desktop.'],['Bagikan','Publikasikan, salin tautan atau QR, kirim lewat WhatsApp atau email.'],['Analisis','Buka hasil, periksa validitas dan reliabilitas, lalu salin laporan otomatis.']].map((x,i)=>`<div class="card soft"><span class="qn">${i+1}</span><h3 style="margin-top:.6rem">${x[0]}</h3><p class="muted small" style="margin-top:.3rem">${x[1]}</p></div>`).join('')}</div></section>
<section class="sec" id="harga"><h2>Paket</h2><div class="grid g3">
${[['Gratis','Rp0','3 survei aktif, 100 respons per survei, ekspor CSV',0],['Pro','Rp49.000 / bulan','Survei tanpa batas, logika lanjutan, laporan otomatis, tim 5 orang',1],['Institusi','Hubungi kami','SSO, API, penyimpanan data di server sendiri, dukungan prioritas',0]].map(p=>`<div class="card price ${p[3]?'hl':''}"><h3>${p[0]}</h3><div class="amt">${p[1]}</div><ul class="small">${p[2].split(', ').map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn ${p[3]?'pri':''}" data-go="auth" data-m="register">Pilih ${p[0]}</button></div>`).join('')}</div>
<p class="muted small">Pembayaran di versi prototipe ini hanya simulasi. Percobaan gratis 14 hari tersedia untuk Pro.</p></section>`);

PG.auth=()=>{const m=R.auth;const wrap=c=>pub(`<div class="auth card stack">${c}</div>`);
 const soc=`<div class="divider">atau</div><div class="row"><button class="btn sp" data-act="social" data-p="Google">Google</button><button class="btn sp" data-act="social" data-p="Facebook">Facebook</button></div><p class="tiny muted">Login sosial hanya simulasi di prototipe ini.</p>`;
 if(m==='register')return wrap(`<h2>Buat akun</h2><form data-form="register" class="stack"><label class="f">Nama lengkap<input type="text" name="name" required autocomplete="name"></label><label class="f">Email<input type="email" name="email" required autocomplete="email"></label><label class="f">Kata sandi<input type="password" name="pw" minlength="8" required autocomplete="new-password"><span class="hint">Minimal 8 karakter.</span></label><label class="chk"><input type="checkbox" name="ok" required> Saya setuju dengan <a data-go="legal" data-t="syarat">Syarat</a> dan <a data-go="legal" data-t="privasi">Kebijakan privasi</a></label><button class="btn pri">Daftar</button></form>${soc}<p class="small">Sudah punya akun? <a href="#" data-go="auth" data-m="login">Masuk</a></p>`);
 if(m==='verify')return wrap(`<h2>Verifikasi email</h2><p class="muted">Kami mengirim kode 6 digit ke <b>${esc(R.tmp.email)}</b>.</p><div class="note ok">Kode simulasi: <b>${R.tmp.code}</b> (di versi server, kode dikirim lewat email)</div><form data-form="verify" class="stack"><label class="f">Kode verifikasi<input type="text" name="code" inputmode="numeric" maxlength="6" required></label><button class="btn pri">Verifikasi</button></form>`);
 if(m==='twofa')return wrap(`<h2>Verifikasi dua langkah</h2><p class="muted">Masukkan kode dari aplikasi autentikator Anda.</p><div class="note ok">Kode simulasi: <b>${R.tmp.code}</b></div><form data-form="twofa" class="stack"><label class="f">Kode 6 digit<input type="text" name="code" inputmode="numeric" maxlength="6" required></label><button class="btn pri">Lanjut</button></form>`);
 if(m==='forgot')return wrap(`<h2>Lupa kata sandi</h2><p class="muted">Masukkan email akun. Kami kirim tautan untuk membuat kata sandi baru.</p><form data-form="forgot" class="stack"><label class="f">Email<input type="email" name="email" required></label><button class="btn pri">Kirim tautan reset</button></form><a href="#" data-go="auth" data-m="login">Kembali ke login</a>`);
 return wrap(`<h2>Masuk</h2><form data-form="login" class="stack"><label class="f">Email atau nama pengguna<input type="text" name="email" required autocomplete="username"></label><label class="f">Kata sandi<input type="password" name="pw" required autocomplete="current-password"></label><button class="btn pri">Masuk</button></form><div class="row"><a href="#" data-go="auth" data-m="forgot" class="small">Lupa kata sandi?</a><span class="sp"></span><a href="#" data-go="auth" data-m="register" class="small">Buat akun</a></div>${soc}<button class="btn" data-act="demologin">Pakai akun demo</button>`)};

PG.dashboard=()=>{const mine=S.surveys,all=S.responses,pub=mine.filter(s=>s.status==='published').length;
 const starts=sum(mine.map(s=>s.starts||0)),comp=starts?Math.min(100,pct(all.length,starts)):0,avg=all.length?mean(all.map(r=>r.end-r.start)):0;
 const days=[...Array(14)].map((_,i)=>Date.now()-(13-i)*DAY);const cnt=days.map(d=>all.filter(r=>new Date(r.end).toDateString()===new Date(d).toDateString()).length);
 POST.push(()=>mk('c_trend',{type:'line',data:{labels:days.map(fd),datasets:[{label:'Respons',data:cnt,borderColor:cssv('--maroon'),backgroundColor:cssv('--coksu')+'55',fill:true,tension:.3,pointRadius:3}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}}));
 return appShell(`<div class="ph"><div><p class="muted small">Halo, ${esc(S.user.name.split(' ')[0])}</p><h2>Dashboard</h2></div>${can()?`<button class="btn pri" data-act="newsurvey">${ic('plus')}Survei baru</button>`:''}</div>
 <div class="grid g4"><div class="card kpi"><b>${mine.filter(s=>s.status!=='archived').length}</b><span>Survei (${pub} aktif)</span></div><div class="card kpi"><b>${all.length}</b><span>Total responden</span></div><div class="card kpi"><b>${comp}%</b><span>Tingkat penyelesaian</span></div><div class="card kpi"><b>${avg?fdur(avg):'-'}</b><span>Waktu isi rata-rata</span></div></div>
 <div class="card"><h3>Respons 14 hari terakhir</h3><div class="chartbox sm" style="margin-top:.8rem"><canvas id="c_trend" role="img" aria-label="Grafik respons harian"></canvas></div></div>
 <div class="grid g2"><div class="card stack"><h3>Survei terbaru</h3>${mine.filter(s=>s.status!=='archived').slice(0,4).map(s=>`<div class="srow"><div class="t"><b>${esc(s.title)}</b><span class="muted small">${S.responses.filter(r=>r.sid===s.id).length} respons</span></div>${statusPill(s)}<button class="btn sm" data-go="results" data-id="${s.id}">Hasil</button></div>`).join('')||'<p class="muted">Belum ada survei.</p>'}</div>
 <div class="card stack"><h3>Aktivitas terakhir</h3>${S.log.slice(0,5).map(l=>`<div class="small"><b>${esc(l.who)}</b> ${esc(l.msg)}<br><span class="muted tiny">${fdt(l.t)}</span></div>`).join('')}</div></div>`,'dashboard')};

PG.surveys=()=>{let L=S.surveys.filter(s=>(R.flt==='all'?s.status!=='archived':s.status===R.flt)&&s.title.toLowerCase().includes(R.sf.toLowerCase()));
 return appShell(`<div class="ph"><h2>Survei saya</h2>${can()?`<button class="btn pri" data-act="newsurvey">${ic('plus')}Survei baru</button>`:''}</div>
 <div class="row"><input type="search" id="sf" placeholder="Cari judul survei" value="${esc(R.sf)}" style="max-width:320px" aria-label="Cari survei"><div class="tabs" style="border:0">${[['all','Semua'],['draft','Draft'],['published','Aktif'],['archived','Arsip']].map(t=>`<button class="${R.flt===t[0]?'on':''}" data-act="flt" data-v="${t[0]}">${t[1]}</button>`).join('')}</div></div>
 ${L.map(s=>{const n=S.responses.filter(r=>r.sid===s.id).length;return `<div class="card"><div class="srow"><div class="t"><b>${esc(s.title)}</b><span class="muted small">${s.questions.length} pertanyaan · ${n} respons · dibuat ${fd(s.created)}</span></div>${statusPill(s)}
 <div class="row">${can()?`<button class="btn sm" data-act="edit" data-id="${s.id}">${ic('edit')}Edit</button>`:''}<button class="btn sm" data-go="results" data-id="${s.id}">${ic('chart')}Hasil</button><button class="btn sm" data-go="distribute" data-id="${s.id}">${ic('share')}Bagikan</button><button class="btn sm ic" data-act="prev" data-id="${s.id}" title="Pratinjau" aria-label="Pratinjau">${ic('eye')}</button>
 ${can()?`<button class="btn sm ic" data-act="dup" data-id="${s.id}" title="Duplikasi" aria-label="Duplikasi">${ic('dup')}</button><button class="btn sm ic" data-act="pubtog" data-id="${s.id}" title="${s.status==='published'?'Tarik dari publikasi':'Publikasikan'}" aria-label="Publish atau unpublish">${ic('bolt')}</button><button class="btn sm ic" data-act="arch" data-id="${s.id}" title="${s.status==='archived'?'Pulihkan':'Arsipkan'}" aria-label="Arsip">${ic('arch')}</button><button class="btn sm ic dng" data-act="del" data-id="${s.id}" title="Hapus" aria-label="Hapus">${ic('trash')}</button>`:''}</div></div></div>`}).join('')||`<div class="card empty">Tidak ada survei yang cocok.${can()?'<br><br><button class="btn pri" data-act="newsurvey">Buat survei pertama</button>':''}</div>`}`,'surveys')};

/* ----- Builder ----- */
function qEditor(s,q,i){const T=QT[q.type],others=s.questions.slice(0,i);
 const body=[];
 if(T.o&&!T.g)body.push(`<label class="f">Pilihan (satu per baris)<textarea data-bq="${q.id}" data-bk="options" data-rr="1">${esc((q.options||[]).join('\n'))}</textarea></label>`);
 if(T.g)body.push(`<div class="grid g2"><label class="f">Baris pernyataan (satu per baris)<textarea data-bq="${q.id}" data-bk="rows">${esc(q.rows.join('\n'))}</textarea></label><label class="f">Kolom skala (satu per baris)<textarea data-bq="${q.id}" data-bk="options">${esc(q.options.join('\n'))}</textarea></label></div>`);
 if(q.type==='slider'||q.type==='number')body.push(`<div class="grid g2"><label class="f">Nilai minimum<input type="number" data-bq="${q.id}" data-bk="min" value="${q.min??''}"></label><label class="f">Nilai maksimum<input type="number" data-bq="${q.id}" data-bk="max" value="${q.max??''}"></label></div>`);
 if(q.type==='date')body.push(`<label class="f">Jenis isian${sel([['date','Tanggal'],['datetime-local','Tanggal dan waktu']],q.dt,`data-bq="${q.id}" data-bk="dt"`)}</label>`);
 if(q.type==='likert')body.push(`<p class="hint">Setiap baris di atas diberi skor 1, 2, 3, dst. dari atas ke bawah.</p>`);
 if(q.type==='file')body.push(`<p class="hint">Responden memilih berkas gambar atau PDF. Prototipe ini hanya menyimpan nama dan ukuran berkas.</p>`);
 const choiceLike=['single','dropdown','multi','likert','nps','rating','slider','number'].includes(q.type);
 let logic='';
 if(choiceLike){
  const gotoOpts=[['','Lanjut berikutnya'],...s.questions.slice(i+1).map((x,j)=>[x.id,`Ke pertanyaan ${i+j+2}`]),['end','Akhiri survei']];
  const valIn=(r,ri)=>(q.options&&!QT[q.type].num||q.type==='likert')?sel((q.type==='likert'?q.options.map((o,k)=>[k+1,`${k+1} · ${o}`]):q.options),r.val,`data-bq="${q.id}" data-bk="r_val" data-ri="${ri}"`):`<input type="number" value="${esc(r.val)}" data-bq="${q.id}" data-bk="r_val" data-ri="${ri}" aria-label="Nilai">`;
  const ops=[['eq','sama dengan'],['ne','bukan'],['ge','≥'],['le','≤']];
  logic=`<details class="lg" ${q.rules.length||q.showIf?'open':''}><summary>Logika (lompat &amp; bersyarat)${q.rules.length||q.showIf?' · aktif':''}</summary><div class="stack" style="margin-top:.7rem">
  <b class="small">Skip logic / percabangan</b>
  ${q.rules.map((r,ri)=>`<div class="row"><span class="small">Jika jawaban</span>${sel(ops,r.op,`data-bq="${q.id}" data-bk="r_op" data-ri="${ri}"`)}${valIn(r,ri)}${sel(gotoOpts,r.goto,`data-bq="${q.id}" data-bk="r_goto" data-ri="${ri}"`)}<button class="btn sm ic dng" data-act="rmrule" data-q="${q.id}" data-ri="${ri}" aria-label="Hapus aturan">${ic('x')}</button></div>`).join('')}
  <button class="btn sm" data-act="addrule" data-q="${q.id}" style="width:fit-content">${ic('plus')}Tambah aturan lompat</button></div></details>`}
 const si=q.showIf||{};
 const cond=i>0?`<details class="lg" ${q.showIf?'open':''}><summary>Tampilkan hanya jika…${q.showIf?' · aktif':''}</summary><div class="row" style="margin-top:.7rem">${sel([['','(selalu tampil)'],...others.map((x,j)=>[x.id,`P${j+1}`])],si.q||'',`data-bq="${q.id}" data-bk="si_q" data-rr="1"`)}${sel([['eq','sama dengan'],['ne','bukan'],['ge','≥'],['le','≤']],si.op||'eq',`data-bq="${q.id}" data-bk="si_op"`)}<input type="text" value="${esc(si.val??'')}" placeholder="nilai" data-bq="${q.id}" data-bk="si_val" style="max-width:200px" aria-label="Nilai syarat"></div><p class="hint" style="margin-top:.4rem">Untuk Likert/rating/NPS isi angkanya. Untuk pilihan, isi teks pilihan persis.</p></details>`:'';
 return `<article class="qcard" data-qid="${q.id}"><div class="qh"><span class="handle" draggable="true" data-drag="${q.id}" title="Seret untuk memindah" aria-hidden="true">${ic('grip')}</span><span class="qn">${i+1}</span><span class="pill">${T.n}</span><span class="sp"></span>
 <button class="btn sm ic" data-act="qup" data-q="${q.id}" aria-label="Naikkan" ${i===0?'disabled':''}>${ic('up')}</button><button class="btn sm ic" data-act="qdn" data-q="${q.id}" aria-label="Turunkan" ${i===s.questions.length-1?'disabled':''}>${ic('down')}</button><button class="btn sm ic" data-act="qdup" data-q="${q.id}" aria-label="Duplikasi pertanyaan">${ic('dup')}</button><button class="btn sm ic dng" data-act="qdel" data-q="${q.id}" aria-label="Hapus pertanyaan">${ic('trash')}</button></div>
 <label class="f"><span class="sr" style="display:none">Teks</span><textarea data-bq="${q.id}" data-bk="text" style="min-height:3.2rem" aria-label="Teks pertanyaan ${i+1}">${esc(q.text)}</textarea></label>
 ${body.join('')}<label class="chk"><input type="checkbox" data-bq="${q.id}" data-bk="required" ${q.required?'checked':''}> Wajib dijawab</label>${cond}${logic}</article>`}
PG.builder=()=>{const s=survey(R.id);if(!s)return PG['404']();const ro=!can();
 return appShell(`<div class="ph"><button class="btn sm" data-go="surveys">← Daftar survei</button><h2 style="flex:1 1 200px">Survey builder</h2>${statusPill(s)}<button class="btn" data-act="prev" data-id="${s.id}">${ic('eye')}Pratinjau</button><button class="btn pri" data-act="pubtog" data-id="${s.id}">${s.status==='published'?'Tarik dari publikasi':'Publikasikan'}</button></div>
 <p class="muted small" style="margin-top:-.6rem">Perubahan tersimpan otomatis sebagai draft.</p>
 <div class="bgrid"><aside class="card stack"><h3>Pengaturan survei</h3>
 <label class="f">Judul<input type="text" data-ss="title" value="${esc(s.title)}"></label>
 <label class="f">Deskripsi<textarea data-ss="desc">${esc(s.desc)}</textarea></label>
 <label class="f">Estimasi waktu (menit)<input type="number" min="1" data-ss="est" value="${s.est}"></label>
 <label class="f">Pesan pembuka<textarea data-ss="welcome">${esc(s.welcome)}</textarea></label>
 <label class="f">Teks persetujuan responden<textarea data-ss="consent">${esc(s.consent)}</textarea></label>
 <label class="f">Pesan penutup<textarea data-ss="thanks">${esc(s.thanks)}</textarea></label>
 <label class="f">Batas waktu pengisian<input type="date" data-ss="deadline" value="${esc(s.deadline)}"></label>
 <label class="f">Kode akses (opsional)<input type="text" data-ss="password" value="${esc(s.password)}" placeholder="kosong = tanpa kode"></label>
 <label class="chk"><input type="checkbox" data-ss="progress" ${s.progress?'checked':''}> Tampilkan progress bar</label>
 <label class="chk"><input type="checkbox" data-ss="oneResp" ${s.oneResp?'checked':''}> Satu respons per perangkat</label>
 <label class="chk"><input type="checkbox" data-ss="anon" ${s.anon?'checked':''}> Anonim (tanpa nama dan email)</label>
 <label class="chk"><input type="checkbox" data-ss="randomize" ${s.randomize?'checked':''}> Acak urutan pertanyaan</label></aside>
 <section class="stack"><div class="note ok small">Tips piping: tulis <b>{{q1}}</b> di teks pertanyaan untuk menampilkan jawaban pertanyaan nomor 1.</div>
 ${s.questions.map((q,i)=>qEditor(s,q,i)).join('')}
 <div class="card soft stack"><h3>Tambah pertanyaan</h3><div class="typegrid">${Object.keys(QT).map(t=>`<button data-act="addq" data-t="${t}">${ic('plus')} ${QT[t].n}</button>`).join('')}</div></div></section></div>`,'surveys')};

/* ----- Distribusi ----- */
PG.distribute=()=>{const s=survey(R.id);if(!s)return PG['404']();const L=link(s),n=S.responses.filter(r=>r.sid===s.id);
 POST.push(()=>{const el=$('#qr');if(el&&window.QRCode){el.innerHTML='';new QRCode(el,{text:L,width:176,height:176,colorDark:'#4A0E1A',colorLight:'#ffffff'})}});
 const emb=`<iframe src="${L}" width="100%" height="640" style="border:0" title="${s.title}"></iframe>`;
 const groups=[...new Set(s.respondents.map(r=>r.group).filter(Boolean))];
 const done=r=>n.some(x=>x.email&&x.email.toLowerCase()===r.email.toLowerCase());
 const shownR=s.respondents.filter(r=>!R.grp||r.group===R.grp);
 return appShell(`<div class="ph"><button class="btn sm" data-go="surveys">← Daftar survei</button><h2 style="flex:1 1 200px">Bagikan: ${esc(s.title)}</h2>${statusPill(s)}</div>
 ${s.status!=='published'?`<div class="note">Survei belum dipublikasikan, jadi responden belum bisa mengisi. ${can()?`<button class="btn sm" data-act="pubtog" data-id="${s.id}">Publikasikan sekarang</button>`:''}</div>`:''}
 <div class="note small">Prototipe ini menyimpan data di browser ini. Tautan di bawah membuka survei yang sama hanya di browser ini. Agar responden lain bisa mengisi dari perangkat mereka, survei perlu dihubungkan ke server atau database bersama.</div>
 <div class="grid g2"><div class="card stack"><h3>Tautan survei</h3><input type="text" readonly value="${esc(L)}" id="lk" aria-label="Tautan survei"><div class="row"><button class="btn pri" data-act="cp" data-v="${esc(L)}">${ic('copy')}Salin tautan</button><button class="btn" data-act="openfill" data-id="${s.id}">Buka halaman isi</button></div>
 <h3 style="margin-top:.5rem">QR code</h3><div class="qr" id="qr"></div><p class="hint">Cetak atau tampilkan di layar. Klik kanan pada gambar untuk menyimpan.</p></div>
 <div class="card stack"><h3>Kode akses</h3><label class="f">Responden harus memasukkan kode ini<input type="text" data-ss="password" value="${esc(s.password)}" placeholder="kosong = tanpa kode"></label>
 <h3>Sematkan di website</h3><div class="code">${esc(emb)}</div><button class="btn sm" data-act="cp" data-v="${esc(emb)}" style="width:fit-content">${ic('copy')}Salin kode sematan</button>
 <h3>WhatsApp &amp; media sosial</h3><div class="row"><a class="btn sm" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent('Mohon isi survei: '+s.title+' '+L)}">WhatsApp</a><a class="btn sm" target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?text=${encodeURIComponent('Mohon isi survei: '+s.title+' '+L)}">X / Twitter</a><a class="btn sm" target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(L)}">Facebook</a></div>
 <p class="hint">Rencana: pengiriman via SMS, chatbot, dan mode kiosk.</p></div></div>
 <div class="card stack"><h3>Undangan email</h3><label class="f">Subjek<input type="text" id="mailsub" value="Mohon bantuan mengisi survei: ${esc(s.title)}"></label><label class="f">Isi<textarea id="mailbody" style="min-height:8rem">Halo,\n\nKami mengundang Anda mengisi survei "${esc(s.title)}". Waktu pengisian sekitar ${s.est} menit.${s.password?'\nKode akses: '+s.password:''}\n\nTautan: ${L}\n\nTerima kasih.</textarea></label><div class="row"><button class="btn" data-act="cpmail">${ic('copy')}Salin isi email</button><span class="hint">Tempel ke email Anda. Pengiriman otomatis perlu server email.</span></div></div>
 <div class="card stack"><div class="ph"><h3 style="flex:1">Daftar responden (${s.respondents.length})</h3>${groups.length?`<select id="grp" aria-label="Segmen">${[['','Semua segmen'],...groups].map(g=>{const [v,l]=Array.isArray(g)?g:[g,g];return `<option value="${esc(v)}" ${R.grp===v?'selected':''}>${esc(l)}</option>`}).join('')}</select>`:''}<button class="btn sm" data-act="remind">Kirim pengingat (simulasi)</button></div>
 <label class="f">Impor dari CSV (kolom: nama, email, kelompok)<textarea id="csvin" placeholder="Rina Ayu,rina@kampus.ac.id,Angkatan 2023"></textarea></label><div class="row"><button class="btn sm pri" data-act="impcsv">Impor teks</button><label class="btn sm" style="cursor:pointer">Pilih berkas CSV<input type="file" id="csvfile" accept=".csv,text/csv" style="display:none"></label></div>
 ${s.respondents.length?`<div class="tbl"><table><tr><th>Nama</th><th>Email</th><th>Segmen</th><th>Status</th></tr>${shownR.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${esc(r.group||'-')}</td><td>${done(r)?'<span class="pill ok">Selesai</span>':'<span class="pill warn">Belum</span>'}</td></tr>`).join('')}</table></div><p class="hint">Status "Selesai" dicocokkan lewat email pada survei yang tidak anonim.</p>`:'<p class="muted small">Belum ada responden terdaftar.</p>'}</div>`,'surveys')};

/* ----- Hasil ----- */
function filterBar(s){const cq=s.questions.filter(q=>CHOICE.includes(q.type));const fq=cq.find(q=>q.id===R.fq);
 return `<div class="card flat row"><b class="small">Filter segmen</b>${sel([['','(semua responden)'],...cq.map(q=>[q.id,q.text.slice(0,50)])],R.fq,'id="fq" aria-label="Pertanyaan filter"')}${fq?sel([['','pilih…'],...fq.options],R.fv,'id="fv" aria-label="Nilai filter"'):''}<label class="chk small"><input type="checkbox" id="excl" ${R.excl?'checked':''}> Buang respons janggal</label></div>`}
function dist(rs,q){let v=vals(rs,q);const T=q.type;let labels,counts;
 if(T==='likert'){labels=q.options.map((o,i)=>i+1);counts=labels.map(l=>v.filter(x=>x===l).length)}
 else if(T==='rating'){labels=[1,2,3,4,5];counts=labels.map(l=>v.filter(x=>x===l).length)}
 else if(T==='nps'){labels=[...Array(11).keys()];counts=labels.map(l=>v.filter(x=>x===l).length)}
 else{const lo=Math.min(...v),hi=Math.max(...v);if(!v.length)return{labels:[],counts:[]};const k=Math.min(8,Math.max(1,hi-lo+1)),w=(hi-lo+1)/k;labels=[...Array(k)].map((_,i)=>w===1?String(lo+i):`${Math.round(lo+i*w)}–${Math.round(lo+(i+1)*w-1)}`);counts=labels.map(()=>0);v.forEach(x=>{counts[Math.min(k-1,Math.floor((x-lo)/w))]++})}
 return{labels,counts}}
function qBlock(s,q,rs,i){const id='c_'+q.id,T=QT[q.type],n=rs.length;let h='',chart=null;
 const row=(l,c,tot)=>`<tr><td>${esc(l)}</td><td class="n">${c}</td><td class="n">${fx(pct(c,tot),1)}%</td></tr>`;
 const freq=(L,C,tot)=>`<div class="tbl"><table><tr><th>Kategori</th><th class="n">Frekuensi</th><th class="n">Persen</th></tr>${L.map((l,j)=>row(l,C[j],tot)).join('')}<tr><th>Total</th><th class="n">${tot}</th><th class="n">100%</th></tr></table></div>`;
 if(CHOICE.includes(q.type)){const C=q.options.map(o=>rs.filter(r=>{const a=r.a[q.id];return Array.isArray(a)?a.includes(o):a===o}).length);const tot=q.type==='multi'?n:sum(C);const pie=R.view[q.id]==='pie'&&q.type!=='multi';
  chart={type:pie?'doughnut':'bar',data:{labels:q.options,datasets:[{data:C,backgroundColor:pal(q.options.length),borderWidth:0}]},options:pie?{plugins:{legend:{position:'right'}}}:{indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{precision:0}}}}};
  h=`<div class="chartbox sm"><canvas id="${id}" role="img" aria-label="Grafik ${esc(q.text)}"></canvas></div>${freq(q.options,C,tot)}${q.type==='multi'?'<p class="hint">Persen dihitung dari jumlah responden (boleh lebih dari 100%).</p>':''}`}
 else if(T.num){const v=vals(rs,q),d=dist(rs,q);chart={type:'bar',data:{labels:d.labels,datasets:[{data:d.counts,backgroundColor:pal(d.labels.length||1),borderWidth:0,borderRadius:6}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}};
  h=`<div class="row small"><span class="pill pri">Rata-rata ${fx(mean(v))}</span><span class="pill">Median ${fx(median(v),1)}</span><span class="pill">Modus ${modes(v).join(', ')||'-'}</span><span class="pill">SD ${fx(sd(v))}</span><span class="pill">n=${v.length}</span></div><div class="chartbox sm"><canvas id="${id}" role="img" aria-label="Sebaran ${esc(q.text)}"></canvas></div>${q.type==='likert'?freq(q.options.map((o,j)=>`${j+1} · ${o}`),d.counts,v.length):freq(d.labels,d.counts,v.length)}`}
 else if(q.type==='text'){const t=rs.map(r=>r.a[q.id]).filter(Boolean),w=words(t),mx=w[0]?.[1]||1,sn={positif:0,netral:0,negatif:0};t.forEach(x=>sn[sig(x)]++);
  h=`<div class="row small"><span class="pill ok">Positif ${sn.positif}</span><span class="pill">Netral ${sn.netral}</span><span class="pill bad">Negatif ${sn.negatif}</span><span class="hint">Analisis sentimen sederhana berbasis kata kunci</span></div>${w.length?`<div class="wc card soft" aria-label="Word cloud">${w.map(([k,c])=>`<span style="font-size:${(.95+c/mx*1.7).toFixed(2)}rem">${esc(k)}</span>`).join('')}</div>`:''}<div class="stack" style="gap:.4rem">${t.slice(0,6).map(x=>`<div class="small card flat" style="padding:.5rem .8rem">${esc(x)} <span class="pill ${sig(x)==='positif'?'ok':sig(x)==='negatif'?'bad':''}">${sig(x)}</span></div>`).join('')||'<p class="muted small">Belum ada jawaban.</p>'}${t.length>6?`<p class="hint">Menampilkan 6 dari ${t.length} jawaban. Lihat semuanya di tab Respons.</p>`:''}</div>`}
 else if(q.type==='grid'){h=`<div class="tbl"><table><tr><th></th>${q.options.map(o=>`<th class="n">${esc(o)}</th>`).join('')}</tr>${q.rows.map(r=>`<tr><td>${esc(r)}</td>${q.options.map(o=>`<td class="n">${rs.filter(x=>x.a[q.id]&&x.a[q.id][r]===o).length}</td>`).join('')}</tr>`).join('')}</table></div>`}
 else if(q.type==='ranking'){const m=q.options.map(o=>{const p=rs.map(r=>(r.a[q.id]||[]).indexOf(o)+1).filter(x=>x>0);return[o,mean(p)]}).sort((a,b)=>a[1]-b[1]);h=`<div class="tbl"><table><tr><th>Peringkat</th><th>Item</th><th class="n">Rata-rata urutan</th></tr>${m.map((x,j)=>`<tr><td>${j+1}</td><td>${esc(x[0])}</td><td class="n">${fx(x[1])}</td></tr>`).join('')}</table></div>`}
 else{const t=rs.map(r=>r.a[q.id]).filter(Boolean);h=`<p class="small muted">${t.length} jawaban. ${q.type==='date'?'Rentang: '+(t.length?[...t].sort()[0]+' s.d. '+[...t].sort().slice(-1)[0]:'-'):''}</p>${t.slice(0,5).map(x=>`<div class="small">${esc(typeof x==='object'?x.name:x)}</div>`).join('')}`}
 if(chart)POST.push(()=>mk(id,chart));
 return `<div class="card stack"><div class="row"><span class="qn">${i+1}</span><h3 style="flex:1 1 200px;font-size:1.05rem">${esc(q.text)}</h3><span class="pill">${T.n}</span>${CHOICE.includes(q.type)&&q.type!=='multi'?`<button class="btn sm" data-act="view" data-q="${q.id}">${R.view[q.id]==='pie'?'Tampilkan bar':'Tampilkan pie'}</button>`:''}${chart?`<button class="btn sm" data-act="png" data-c="${id}">PNG</button>`:''}</div>${h}</div>`}
PG.results=()=>{const s=survey(R.id);if(!s)return PG['404']();const rs=resp(s),raw=resp(s,true),T=R.tab;
 const tabs=[['ringkas','Ringkasan'],['statistik','Statistik'],['instrumen','Uji instrumen'],['respons','Respons'],['laporan','Laporan'],['ekspor','Ekspor']];
 let body='';
 if(!raw.length)body=`<div class="card empty"><h3>Belum ada respons</h3><p>Bagikan tautan survei, atau isi sendiri lewat halaman isi.</p><div class="row" style="justify-content:center;margin-top:1rem"><button class="btn pri" data-go="distribute" data-id="${s.id}">Bagikan survei</button><button class="btn" data-act="openfill" data-id="${s.id}">Isi survei</button></div></div>`;
 else if(T==='ringkas')body=resTab(s,rs);else if(T==='statistik')body=statTab(s,rs);else if(T==='instrumen')body=instTab(s,rs);else if(T==='respons')body=respTab(s,raw);else if(T==='laporan')body=repTab(s,rs);else body=expTab(s,rs);
 return appShell(`<div class="ph"><button class="btn sm" data-go="surveys">← Daftar survei</button><h2 style="flex:1 1 200px">${esc(s.title)}</h2>${statusPill(s)}</div><div class="tabs" role="tablist">${tabs.map(t=>`<button role="tab" class="${T===t[0]?'on':''}" data-act="rtab" data-v="${t[0]}" aria-selected="${T===t[0]}">${t[1]}</button>`).join('')}</div>${raw.length&&T!=='respons'?filterBar(s):''}${body}`,'surveys')};
function resTab(s,rs){const raw=resp(s,true),starts=Math.max(s.starts||0,raw.length),d=rs.map(r=>r.end-r.start),days=[...Array(14)].map((_,i)=>Date.now()-(13-i)*DAY),cnt=days.map(x=>rs.filter(r=>new Date(r.end).toDateString()===new Date(x).toDateString()).length);
 POST.push(()=>mk('c_trend',{type:'line',data:{labels:days.map(fd),datasets:[{data:cnt,borderColor:cssv('--maroon'),backgroundColor:cssv('--coksu')+'55',fill:true,tension:.3}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}}));
 return `<div class="grid g4"><div class="card kpi"><b>${rs.length}</b><span>Responden dianalisis</span></div><div class="card kpi"><b>${fx(pct(raw.length,starts),1)}%</b><span>Tingkat penyelesaian</span></div><div class="card kpi"><b>${d.length?fdur(mean(d)):'-'}</b><span>Waktu isi rata-rata</span></div><div class="card kpi"><b>${raw.filter(r=>flagOf(s,r).length).length}</b><span>Respons janggal</span></div></div>
 <div class="card"><h3>Respons per hari</h3><div class="chartbox sm" style="margin-top:.7rem"><canvas id="c_trend" role="img" aria-label="Respons per hari"></canvas></div></div>${s.questions.map((q,i)=>qBlock(s,q,rs,i)).join('')}`}
function statTab(s,rs){const nq=numQ(s);if(!R.c1||!nq.find(q=>q.id===R.c1))R.c1=nq[0]?.id||'';if(!R.c2||!nq.find(q=>q.id===R.c2))R.c2=nq[1]?.id||R.c1;
 const cat=s.questions.filter(q=>['single','dropdown','likert','nps','rating'].includes(q.type));if(!R.x1||!cat.find(q=>q.id===R.x1))R.x1=cat[0]?.id||'';if(!R.x2||!cat.find(q=>q.id===R.x2))R.x2=cat[1]?.id||R.x1;
 const label=(q,v)=>q.type==='likert'?`${v} · ${q.options[v-1]||''}`:String(v);
 const desc=`<div class="card stack"><h3>Statistik deskriptif</h3><div class="tbl"><table><tr><th>Variabel</th><th class="n">N</th><th class="n">Min</th><th class="n">Maks</th><th class="n">Mean</th><th class="n">Median</th><th class="n">Modus</th><th class="n">Std. dev</th><th class="n">Varians</th></tr>${nq.map((q,i)=>{const v=vals(rs,q);return `<tr><td>P${s.questions.indexOf(q)+1} ${esc(q.text.slice(0,42))}</td><td class="n">${v.length}</td><td class="n">${fx(Math.min(...v),0)}</td><td class="n">${fx(Math.max(...v),0)}</td><td class="n">${fx(mean(v))}</td><td class="n">${fx(median(v),1)}</td><td class="n">${modes(v).join(', ')}</td><td class="n">${fx(sd(v))}</td><td class="n">${fx(vari(v))}</td></tr>`}).join('')}</table></div></div>`;
 let cor='<p class="muted small">Butuh minimal dua pertanyaan numerik.</p>';
 if(nq.length>=2){const a=nq.find(q=>q.id===R.c1),b=nq.find(q=>q.id===R.c2),P=rs.filter(r=>r.a[a.id]!=null&&r.a[b.id]!=null),r=pearson(P.map(x=>+x.a[a.id]),P.map(x=>+x.a[b.id])),rt=rtabel(P.length);
  cor=`<div class="grid g2">${sel(nq.map(q=>[q.id,`P${s.questions.indexOf(q)+1} ${q.text.slice(0,40)}`]),R.c1,'id="c1" aria-label="Variabel X"')}${sel(nq.map(q=>[q.id,`P${s.questions.indexOf(q)+1} ${q.text.slice(0,40)}`]),R.c2,'id="c2" aria-label="Variabel Y"')}</div>
  <div class="note ok"><b>r Pearson = ${fx(r,3)}</b> (n=${P.length}). Hubungan ${Number.isFinite(r)?corrLabel(r):'-'}. r tabel (α=0,05) = ${fx(rt,3)}, sehingga korelasi ${Math.abs(r)>rt?'<b>signifikan</b>':'<b>tidak signifikan</b>'}.</div>
  <div class="tbl"><table><tr><th></th>${nq.map(q=>`<th class="n">P${s.questions.indexOf(q)+1}</th>`).join('')}</tr>${nq.map(a2=>`<tr><th>P${s.questions.indexOf(a2)+1}</th>${nq.map(b2=>{const P2=rs.filter(r2=>r2.a[a2.id]!=null&&r2.a[b2.id]!=null);const rr=pearson(P2.map(x=>+x.a[a2.id]),P2.map(x=>+x.a[b2.id]));return `<td class="n" style="${a2===b2?'':`background:color-mix(in srgb,var(--coksu) ${Math.round(Math.abs(rr||0)*60)}%,transparent)`}">${fx(rr,2)}</td>`}).join('')}</tr>`).join('')}</table></div>`}
 let cross='<p class="muted small">Butuh minimal dua pertanyaan kategorikal.</p>';
 if(cat.length>=2){const a=cat.find(q=>q.id===R.x1),b=cat.find(q=>q.id===R.x2),A=a.type==='single'||a.type==='dropdown'?a.options:[...new Set(vals(rs,a))].sort((x,y)=>x-y),B=b.type==='single'||b.type==='dropdown'?b.options:[...new Set(vals(rs,b))].sort((x,y)=>x-y);
  const cnt=(x,y)=>rs.filter(r=>String(r.a[a.id])===String(x)&&String(r.a[b.id])===String(y)).length;
  cross=`<div class="grid g2">${sel(cat.map(q=>[q.id,`P${s.questions.indexOf(q)+1} ${q.text.slice(0,40)}`]),R.x1,'id="x1" aria-label="Baris"')}${sel(cat.map(q=>[q.id,`P${s.questions.indexOf(q)+1} ${q.text.slice(0,40)}`]),R.x2,'id="x2" aria-label="Kolom"')}</div><div class="tbl"><table><tr><th>${esc(a.text.slice(0,24))} ↓ / ${esc(b.text.slice(0,24))} →</th>${B.map(y=>`<th class="n">${esc(label(b,y))}</th>`).join('')}<th class="n">Total</th></tr>${A.map(x=>{const t=sum(B.map(y=>cnt(x,y)));return `<tr><td>${esc(label(a,x))}</td>${B.map(y=>{const c=cnt(x,y);return `<td class="n">${c} <span class="muted tiny">(${fx(pct(c,t),0)}%)</span></td>`}).join('')}<td class="n"><b>${t}</b></td></tr>`}).join('')}</table></div><p class="hint">Persen dihitung per baris.</p>`}
 return desc+`<div class="card stack"><h3>Korelasi</h3>${cor}</div><div class="card stack"><h3>Tabulasi silang (cross-tab)</h3>${cross}</div>`}
function instrument(s,rs){const nq=numQ(s).filter(q=>q.type==='likert'||q.type==='rating'||q.type==='slider');if(!R.inst)R.inst=s.questions.filter(q=>q.type==='likert').map(q=>q.id);
 const items=nq.filter(q=>R.inst.includes(q.id));const M=rs.filter(r=>items.every(q=>r.a[q.id]!=null)).map(r=>items.map(q=>+r.a[q.id]));return{nq,items,M}}
function instTab(s,rs){const{nq,items,M}=instrument(s,rs);
 if(!nq.length)return `<div class="card empty">Tambahkan pertanyaan Likert untuk melakukan uji validitas dan reliabilitas.</div>`;
 const n=M.length,rt=rtabel(n),tot=M.map(sum);let rows='',valid=0;
 items.forEach((q,j)=>{const x=M.map(r=>r[j]),y=M.map((r,k)=>tot[k]-r[j]),r=pearson(x,y),ok=r>rt;if(ok)valid++;const sub=M.map(r=>sum(r)-r[j]);const al=items.length>2?alpha(M.map(r=>r.filter((_,k)=>k!==j))):NaN;rows+=`<tr><td>P${s.questions.indexOf(q)+1} ${esc(q.text.slice(0,52))}</td><td class="n">${fx(r,3)}</td><td class="n">${fx(rt,3)}</td><td>${ok?'<span class="pill ok">Valid</span>':'<span class="pill bad">Tidak valid</span>'}</td><td class="n">${fx(al,3)}</td></tr>`});
 const a=alpha(M);
 return `<div class="card stack"><h3>Pilih butir instrumen</h3><div class="stack" style="gap:.3rem">${nq.map(q=>`<label class="chk"><input type="checkbox" data-inst="${q.id}" ${R.inst.includes(q.id)?'checked':''}> P${s.questions.indexOf(q)+1} ${esc(q.text)}</label>`).join('')}</div><p class="hint">Hanya responden yang menjawab semua butir terpilih yang dihitung (n = ${n}).</p></div>
 ${items.length<2||n<4?`<div class="note">Pilih minimal 2 butir dan pastikan ada cukup responden.</div>`:`
 <div class="card stack"><h3>Uji validitas</h3><p class="small muted">Corrected item-total correlation (Pearson). Kriteria: r hitung &gt; r tabel (df = ${n-2}, α = 0,05, dua sisi).</p><div class="tbl"><table><tr><th>Butir</th><th class="n">r hitung</th><th class="n">r tabel</th><th>Keputusan</th><th class="n">Alpha jika dihapus</th></tr>${rows}</table></div>
 <div class="note ok"><b>Interpretasi:</b> ${valid} dari ${items.length} butir valid.${valid<items.length?' Butir yang tidak valid sebaiknya direvisi atau dikeluarkan sebelum analisis lanjutan.':' Seluruh butir layak dipakai.'}</div></div>
 <div class="card stack"><h3>Uji reliabilitas</h3><div class="grid g3"><div class="card kpi soft"><b>${fx(a,3)}</b><span>Cronbach's Alpha</span></div><div class="card kpi soft"><b>${items.length}</b><span>Jumlah butir</span></div><div class="card kpi soft"><b>${n}</b><span>Responden valid</span></div></div>
 <div class="note ${a>=.6?'ok':''}"><b>Interpretasi:</b> α = ${fx(a,3)} termasuk reliabilitas <b>${alphaLabel(a)}</b>. Kriteria: α &gt; 0,60 atau 0,70, sehingga instrumen ${a>.7?'<b>reliabel</b>':a>.6?'<b>cukup reliabel</b>':'<b>belum reliabel</b>'}.</div></div>`}`}
function respTab(s,raw){return `<div class="card stack"><h3>Daftar respons dan pelacakan</h3><div class="tbl"><table><tr><th>#</th><th>Status</th><th>Mulai</th><th>Selesai</th><th>Durasi</th><th>Perangkat</th><th>IP</th><th>Lokasi</th><th>Catatan</th></tr>${raw.slice().reverse().slice(0,60).map((r,i)=>{const f=flagOf(s,r);return `<tr><td>${raw.length-i}</td><td><span class="pill ok">Selesai</span></td><td>${fdt(r.start)}</td><td>${fdt(r.end)}</td><td class="n">${fdur(r.end-r.start)}</td><td>${esc(r.device)}</td><td class="muted">tidak dicatat</td><td class="muted">-</td><td>${f.length?`<span class="pill bad">${f.join(', ')}</span>`:''}${r.name?esc(r.name):''}</td></tr>`}).join('')}</table></div><p class="hint">IP dan lokasi tidak tersedia tanpa server. Respons yang terlalu cepat atau berjawaban seragam ditandai sebagai janggal.</p></div>`}
function sections(s,rs){const nq=numQ(s),lk=s.questions.filter(q=>q.type==='likert'),{items,M}=instrument(s,rs),n=M.length,a=alpha(M),rt=rtabel(n);
 const G={};G.pend=`I. PENDAHULUAN\n1. Latar belakang\n${s.desc||'(isi latar belakang)'}\n\n2. Tujuan survei\nUmum: memperoleh gambaran tentang topik "${s.title}".\nKhusus: mengukur ${lk.length} butir pernyataan dan menganalisis hubungan antarvariabel.\n\n3. Ruang lingkup\nPopulasi dan sampel: ${rs.length} responden yang mengisi survei.`;
 G.metode=`II. METODOLOGI PENELITIAN\nDesain: kuantitatif deskriptif dengan kuesioner daring.\nTeknik sampling: sampel tautan terbuka (convenience sampling), n = ${rs.length}.\nTeknik pengumpulan data: kuesioner (${s.questions.length} pertanyaan).\nInstrumen: skala Likert 1–${lk[0]?lk[0].options.length:5}, ${lk.length} butir.\nTeknik analisis: statistik deskriptif, uji validitas dan reliabilitas, korelasi Pearson.`;
 G.uji=items.length>1&&n>3?`III. UJI INSTRUMEN\nValiditas (corrected item-total correlation, r tabel = ${fx(rt,3)}):\n${items.map((q,j)=>{const r=pearson(M.map(x=>x[j]),M.map(x=>sum(x)-x[j]));return `- P${s.questions.indexOf(q)+1}: r hitung ${fx(r,3)} → ${r>rt?'valid':'tidak valid'}`}).join('\n')}\nReliabilitas: Cronbach's Alpha = ${fx(a,3)} (${alphaLabel(a)}).`:'III. UJI INSTRUMEN\n(Data belum cukup untuk uji validitas dan reliabilitas.)';
 G.desk=`IV. ANALISIS DESKRIPTIF\n${nq.map(q=>{const v=vals(rs,q);return `- ${q.text}: mean ${fx(mean(v))}, median ${fx(median(v),1)}, modus ${modes(v).join('/')}, SD ${fx(sd(v))}, min ${Math.min(...v)}, maks ${Math.max(...v)}`}).join('\n')}`;
 const best=nq.map(q=>[q,mean(vals(rs,q))/scaleMax(q)]).sort((x,y)=>y[1]-x[1]);
 G.simp=`VIII. KESIMPULAN DAN SARAN (ringkasan otomatis)\n${best.length?`Aspek dengan skor tertinggi: "${best[0][0].text}" (rata-rata ${fx(mean(vals(rs,best[0][0])))}). Aspek terendah: "${best.slice(-1)[0][0].text}" (rata-rata ${fx(mean(vals(rs,best.slice(-1)[0][0])))}).`:''}\nSaran: prioritaskan perbaikan pada aspek dengan skor terendah dan lakukan survei lanjutan untuk mengukur perubahannya.`;return G}
function repTab(s,rs){const G=sections(s,rs);if(!R.rep)R.rep={tpl:'akademik',on:{pend:1,metode:1,uji:1,desk:1,simp:1}};
 const T={akademik:['pend','metode','uji','desk','simp'],ringkas:['desk','simp'],eksekutif:['simp']};const keys=Object.keys(R.rep.on).filter(k=>R.rep.on[k]);const txt=`LAPORAN SURVEI: ${s.title.toUpperCase()}\nDibuat otomatis pada ${fdt(Date.now())}\n\n`+keys.map(k=>G[k]).join('\n\n')+'\n\nCatatan: periksa dan sesuaikan interpretasi sebelum dimasukkan ke laporan resmi.';
 return `<div class="card stack"><h3>Laporan otomatis</h3><div class="row"><label class="f" style="min-width:200px">Template${sel([['akademik','Akademik lengkap'],['ringkas','Ringkas'],['eksekutif','Eksekutif']],R.rep.tpl,'id="tpl"')}</label></div><div class="row">${[['pend','Pendahuluan'],['metode','Metodologi'],['uji','Uji instrumen'],['desk','Deskriptif'],['simp','Kesimpulan']].map(k=>`<label class="chk small"><input type="checkbox" data-rep="${k[0]}" ${R.rep.on[k[0]]?'checked':''}> ${k[1]}</label>`).join('')}</div>
 <textarea id="reptxt" readonly style="min-height:22rem;font-family:ui-monospace,Menlo,monospace;font-size:.82rem">${esc(txt)}</textarea><div class="row"><button class="btn pri" data-act="cpid" data-id="reptxt">${ic('copy')}Salin laporan</button></div></div>
 <div class="card stack"><h3>Laporan terjadwal</h3><p class="small muted">Kirim ringkasan hasil ke email secara berkala.</p><form data-form="sched" class="row"><input type="email" name="email" placeholder="email@tujuan.com" required style="max-width:260px" value="${esc(S.sched?.email||S.user.email)}">${sel([['harian','Harian'],['mingguan','Mingguan'],['bulanan','Bulanan']],S.sched?.freq||'mingguan','name="freq"')}<button class="btn">Simpan jadwal</button></form>${S.sched?`<span class="pill ok">Aktif: ${S.sched.freq} ke ${esc(S.sched.email)} (simulasi)</span>`:''}</div>`}
function csvOf(s,rs,sep=','){const cols=[['ID',r=>r.id],['Mulai',r=>new Date(r.start).toISOString()],['Selesai',r=>new Date(r.end).toISOString()],['Durasi_detik',r=>Math.round((r.end-r.start)/1000)],['Perangkat',r=>r.device]];
 s.questions.forEach((q,i)=>{if(q.type==='grid')q.rows.forEach(rw=>cols.push([`P${i+1}_${rw}`,r=>(r.a[q.id]||{})[rw]]));else cols.push([`P${i+1}_${q.text}`,r=>{const a=r.a[q.id];return Array.isArray(a)?a.join(q.type==='ranking'?' > ':'; '):typeof a==='object'&&a?a.name:a}])});
 const e=v=>{v=v==null?'':String(v);return v.includes(sep)||v.includes('"')||v.includes('\n')?'"'+v.replace(/"/g,'""')+'"':v};
 return [cols.map(c=>e(c[0])).join(sep),...rs.map(r=>cols.map(c=>e(c[1](r))).join(sep))].join('\n')}
function spssOf(s,rs){const V=[],lab=[],vl=[];s.questions.forEach((q,i)=>{const T=QT[q.type];
 if(T.num){V.push({n:`P${i+1}`,f:r=>r.a[q.id]});lab.push(`P${i+1} "${q.text.replace(/"/g,"'").slice(0,80)}"`)}
 else if(['single','dropdown'].includes(q.type)){V.push({n:`P${i+1}`,f:r=>q.options.indexOf(r.a[q.id])+1||null});lab.push(`P${i+1} "${q.text.replace(/"/g,"'").slice(0,80)}"`);vl.push(`P${i+1} ${q.options.map((o,k)=>`${k+1} "${o.replace(/"/g,"'")}"`).join(' ')}`)}
 else if(q.type==='multi')q.options.forEach((o,k)=>{V.push({n:`P${i+1}_${k+1}`,f:r=>(r.a[q.id]||[]).includes(o)?1:0});lab.push(`P${i+1}_${k+1} "${q.text.slice(0,50).replace(/"/g,"'")}: ${o.replace(/"/g,"'")}"`)})});
 return `* Sintaks SPSS dari ${s.title}.\nDATA LIST FREE / ${V.map(v=>v.n).join(' ')}.\nBEGIN DATA\n${rs.map(r=>V.map(v=>{const x=v.f(r);return x==null?'.':x}).join(' ')).join('\n')}\nEND DATA.\nVARIABLE LABELS\n${lab.join('\n')}.\nVALUE LABELS\n${vl.map(x=>'/'+x).join('\n').replace(/^\//,'')}.\nEXECUTE.`}
function expTab(s,rs){return `<div class="card stack"><h3>Ekspor data</h3><p class="small muted">Pilih format. Isi muncul di bawah dan otomatis disalin. Tempel ke Excel, Notepad, atau SPSS Syntax Editor.</p><div class="row">
 <button class="btn" data-act="exp" data-k="csv">${ic('file')}CSV</button><button class="btn" data-act="exp" data-k="tsv">${ic('file')}Excel (tempel)</button><button class="btn" data-act="exp" data-k="spss">${ic('file')}Sintaks SPSS</button><button class="btn" data-act="exp" data-k="json">${ic('file')}JSON (API)</button><button class="btn" data-act="exp" data-k="xml">${ic('file')}XML</button></div>
 <textarea id="exptxt" readonly style="min-height:16rem;font-family:ui-monospace,Menlo,monospace;font-size:.8rem" placeholder="Klik salah satu format di atas"></textarea><div class="row"><button class="btn pri" data-act="cpid" data-id="exptxt">${ic('copy')}Salin lagi</button><button class="btn" data-act="exp" data-k="dl">Coba unduh berkas</button></div>
 <p class="hint">Grafik bisa disimpan sebagai gambar lewat tombol PNG pada tab Ringkasan. Ekspor PDF: salin laporan dari tab Laporan lalu tempel ke dokumen Anda. Pengunduhan langsung bisa diblokir di tampilan ini.</p></div>`}

/* ----- Isi survei ----- */
function qInput(s,q){const a=F.answers[q.id],id=q.id;
 const nm=`name="f_${id}"`;
 switch(q.type){
 case'single':return `<div class="stack" style="gap:.5rem">${q.options.map(o=>`<label class="opt ${a===o?'on':''}"><input type="radio" ${nm} data-fi="${id}" value="${esc(o)}" ${a===o?'checked':''}>${esc(o)}</label>`).join('')}</div>`;
 case'multi':return `<div class="stack" style="gap:.5rem">${q.options.map(o=>`<label class="opt ${(a||[]).includes(o)?'on':''}"><input type="checkbox" data-fi="${id}" value="${esc(o)}" ${(a||[]).includes(o)?'checked':''}>${esc(o)}</label>`).join('')}<span class="hint">Boleh pilih lebih dari satu.</span></div>`;
 case'dropdown':return `<select data-fs="${id}" aria-label="Pilih jawaban"><option value="">Pilih salah satu…</option>${q.options.map(o=>`<option ${a===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
 case'likert':return `<div class="scale" style="grid-template-columns:repeat(auto-fit,minmax(${q.options.length>5?70:100}px,1fr))">${q.options.map((o,k)=>`<label class="${a===k+1?'on':''}"><input type="radio" ${nm} data-fi="${id}" data-num="1" value="${k+1}" ${a===k+1?'checked':''} style="position:absolute;opacity:0"><b>${k+1}</b>${esc(o)}</label>`).join('')}</div>`;
 case'nps':return `<div><div class="scale npsg">${[...Array(11).keys()].map(k=>`<label class="${a===k?'on':''}"><input type="radio" ${nm} data-fi="${id}" data-num="1" value="${k}" ${a===k?'checked':''} style="position:absolute;opacity:0"><b style="font-size:1rem">${k}</b></label>`).join('')}</div><div class="row small muted"><span>Sangat tidak mungkin</span><span class="sp"></span><span>Sangat mungkin</span></div></div>`;
 case'rating':return `<div class="stars" role="radiogroup" aria-label="Rating">${[1,2,3,4,5].map(k=>`<button type="button" data-act="star" data-q="${id}" data-v="${k}" class="${a>=k?'on':''}" role="radio" aria-checked="${a===k}" aria-label="${k} bintang">★</button>`).join('')}</div>`;
 case'slider':{const mn=q.min??0,mx=q.max??100,v=a??Math.round((+mn+ +mx)/2);return `<div class="stack" style="gap:.3rem"><input type="range" min="${mn}" max="${mx}" value="${v}" data-fr="${id}" aria-label="Slider"><div class="row small muted"><span>${mn}</span><span class="sp"></span><b style="color:var(--fg);font-size:1.1rem" id="rv_${id}">${a==null?'(geser)':a}</b><span class="sp"></span><span>${mx}</span></div></div>`}
 case'text':return `<textarea data-fin="${id}" placeholder="Tulis jawaban Anda">${esc(a||'')}</textarea>`;
 case'number':return `<input type="number" data-fin="${id}" value="${esc(a??'')}" ${q.min!==''&&q.min!=null?`min="${q.min}"`:''} ${q.max!==''&&q.max!=null?`max="${q.max}"`:''} inputmode="decimal" aria-label="Angka">`;
 case'date':return `<input type="${q.dt||'date'}" data-fin="${id}" value="${esc(a||'')}" aria-label="Tanggal">`;
 case'file':return `<input type="file" data-ff="${id}" accept="image/*,.pdf">${a?`<p class="small muted">Dipilih: ${esc(a.name)} (${Math.round(a.size/1024)} KB)</p>`:''}`;
 case'grid':return `<div class="tbl"><table><tr><th></th>${q.options.map(o=>`<th class="n" style="text-align:center">${esc(o)}</th>`).join('')}</tr>${q.rows.map((r,ri)=>`<tr><td>${esc(r)}</td>${q.options.map(o=>`<td style="text-align:center"><input type="radio" name="g_${id}_${ri}" data-fg="${id}" data-row="${esc(r)}" value="${esc(o)}" ${a&&a[r]===o?'checked':''} aria-label="${esc(r)}: ${esc(o)}"></td>`).join('')}</tr>`).join('')}</table></div>`;
 case'ranking':{const L=a||q.options;return `<div class="stack" style="gap:.4rem">${L.map((o,k)=>`<div class="rk"><span class="qn">${k+1}</span><span style="flex:1">${esc(o)}</span><button type="button" class="btn sm ic" data-act="rk" data-q="${id}" data-i="${k}" data-d="-1" aria-label="Naikkan" ${k===0?'disabled':''}>${ic('up')}</button><button type="button" class="btn sm ic" data-act="rk" data-q="${id}" data-i="${k}" data-d="1" aria-label="Turunkan" ${k===L.length-1?'disabled':''}>${ic('down')}</button></div>`).join('')}<span class="hint">Urutkan dari yang paling utama.</span></div>`}}
 return ''}
function devOf(){const u=navigator.userAgent;const os=/Android/.test(u)?'Android':/iPhone|iPad/.test(u)?'iOS':/Windows/.test(u)?'Windows':/Mac/.test(u)?'macOS':/Linux/.test(u)?'Linux':'Lainnya';const b=/Edg\//.test(u)?'Edge':/Chrome\//.test(u)?'Chrome':/Firefox\//.test(u)?'Firefox':/Safari\//.test(u)?'Safari':'Browser';return os+' · '+b}
PG.fill=()=>{const s=survey(F&&F.sid);if(!s)return PG['404']();const live=F.mode==='live';const brand=`<div class="row" style="flex:1;justify-content:space-between;flex-wrap:nowrap"><span class="logo" style="cursor:default"><i>${ic('chart')}</i>${esc(S.prefs.logo)}</span><button class="btn sm" data-act="${live?'leave':'closeprev'}">${live?'Tutup':'← Kembali'}</button></div>`;
 let inner='';
 if(live&&(s.status!=='published'||isClosed(s)))inner=`<div class="card empty"><h2>${isClosed(s)?'Survei sudah ditutup':'Survei belum dibuka'}</h2><p style="margin-top:.5rem">${isClosed(s)?'Batas waktu pengisian telah lewat.':'Pemilik survei belum mempublikasikannya.'}</p></div>`;
 else if(live&&s.oneResp&&S.done[s.id]&&F.step!=='done')inner=`<div class="card empty"><h2>Anda sudah mengisi survei ini</h2><p style="margin-top:.5rem">Survei ini hanya menerima satu respons per perangkat.</p></div>`;
 else{const O=ord(s),total=O.length,pos=F.hist.length;
  if(F.step==='gate')inner=`<div class="card stack"><h2>${esc(s.title)}</h2><p class="muted">Survei ini memerlukan kode akses.</p><form data-form="gate" class="stack"><label class="f">Kode akses<input type="text" name="code" autocomplete="off" required></label><button class="btn pri">Masuk</button></form></div>`;
  else if(F.step==='welcome')inner=`<div class="card stack"><h2>${esc(s.title)}</h2><p>${esc(s.desc)}</p><p class="muted">${esc(s.welcome)}</p><div class="row small"><span class="pill">${total} pertanyaan</span><span class="pill">± ${s.est} menit</span>${s.deadline?`<span class="pill">Sampai ${fd(s.deadline)}</span>`:''}<span class="pill ${s.anon?'ok':''}">${s.anon?'Anonim':'Identitas diminta'}</span></div>
  <form data-form="start" class="stack">${s.anon?'':`<div class="grid g2"><label class="f">Nama<input type="text" name="name" required value="${esc(F.name)}"></label><label class="f">Email<input type="email" name="email" required value="${esc(F.email)}"></label></div>`}<label class="chk"><input type="checkbox" name="consent" required ${F.consent?'checked':''}> ${esc(s.consent)}</label><button class="btn pri" style="align-self:flex-start">Mulai survei</button></form></div>`;
  else if(F.step==='q'){const q=O[F.idx];const visibleTotal=O.filter(shown).length;const p=Math.round(pos/Math.max(1,visibleTotal)*100);
   inner=`${s.progress?`<div><div class="row small muted"><span>Pertanyaan ${pos+1} dari ${visibleTotal}</span><span class="sp"></span><span>${p}%${p>=50&&p<100?' · setengah jalan!':''}</span></div><div class="prog" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p}%"></i></div></div>`:''}
   <div class="card stack" id="qbox"><h2 style="font-size:1.35rem">${esc(pipe(s,q.text))}${q.required?' <span style="color:var(--bad)" aria-label="wajib">*</span>':''}</h2>${qInput(s,q)}<p id="qerr" class="small" style="color:var(--bad)" role="alert"></p></div>
   <div class="row"><button class="btn" data-act="fback" ${pos===0?'disabled':''}>← Kembali</button><span class="sp"></span><button class="btn pri" data-act="fnext">${nextFrom(s,F.idx)>=O.length?'Lanjut ke kirim':'Lanjut →'}</button></div>`}
  else if(F.step==='submit')inner=`<div class="card stack"><h2>Siap dikirim</h2><p class="muted">Satu langkah terakhir untuk memastikan Anda bukan robot.</p><form data-form="submit" class="stack"><div class="hp" aria-hidden="true"><label>Website<input type="text" name="website" tabindex="-1" autocomplete="off"></label></div><label class="f">Berapa ${F.cap[0]} + ${F.cap[1]}?<input type="number" name="cap" required inputmode="numeric" style="max-width:140px"></label><div class="row"><button class="btn" type="button" data-act="fback">← Periksa jawaban</button><button class="btn pri">${live?'Kirim jawaban':'Selesai pratinjau'}</button></div></form></div>`;
  else inner=`<div class="card stack" style="text-align:center;align-items:center"><div class="err" style="font-size:4rem">✓</div><h2>Terima kasih!</h2><p>${esc(s.thanks)}</p><div class="row" style="justify-content:center"><span class="pill pri">${F.pts} poin</span><span class="pill ok">Badge: ${F.pts>=100?'Responden Teladan':F.pts>=50?'Responden Aktif':'Responden Baru'}</span></div>${live?'':'<p class="muted small">Ini pratinjau, jawaban tidak disimpan.</p>'}<button class="btn" data-act="${live?'leave':'closeprev'}">${live?'Selesai':'Kembali ke builder'}</button></div>`}
 const tb=live?'':`<div class="card flat row"><span class="pill warn">Mode pratinjau</span><span class="sp"></span>${[['100%','Desktop'],['720px','Tablet'],['390px','Ponsel']].map(w=>`<button class="btn sm ${F.w===w[0]?'pri':''}" data-act="pw" data-v="${w[0]}">${w[1]}</button>`).join('')}<button class="btn sm" data-act="restart">Ulangi</button></div>`;
 return `<div class="wrap"><header class="top" style="justify-content:space-between">${brand}</header><div class="fillwrap stack">${tb}<div class="preview-frame stack" style="width:100%;max-width:${live?'100%':F.w}">${inner}</div></div>${footer()}</div>`};

/* ----- Pengaturan, profil, tim ----- */
PG.settings=()=>{const p=S.prefs,T=R.stab;let b='';
 if(T==='tampilan')b=`<div class="card stack"><h3>Tema &amp; aksesibilitas</h3><div class="grid g2"><label class="f">Mode tampilan${sel([['system','Ikuti perangkat'],['light','Terang'],['dark','Gelap (dark mode)']],p.theme,'data-pref="theme"')}</label><label class="f">Font${sel(['Plus Jakarta Sans','Atkinson Hyperlegible','Lora'],p.font,'data-pref="font"')}</label></div>
 <label class="chk"><input type="checkbox" data-pref="big" ${p.big?'checked':''}> Font besar</label><label class="chk"><input type="checkbox" data-pref="hc" ${p.hc?'checked':''}> Kontras tinggi</label><p class="hint">Halaman memakai heading, label formulir, dan atribut ARIA agar terbaca oleh screen reader.</p></div>
 <div class="card stack"><h3>Branding &amp; kustomisasi</h3><label class="f">Nama / logo teks<input type="text" data-pref="logo" value="${esc(p.logo)}"></label><div class="row">${[['maroon','Maroon–Coksu'],['mocha','Merah mocha'],['anggur','Anggur–Rose']].map(c=>`<button class="btn ${p.brand===c[0]?'pri':''}" data-act="brand" data-v="${c[0]}">${c[1]}</button>`).join('')}</div>
 <label class="f">CSS kustom<textarea data-pref="css" placeholder=".card{border-radius:4px}" style="font-family:ui-monospace,monospace">${esc(p.css)}</textarea></label></div>`;
 else if(T==='keamanan')b=`<div class="card stack"><h3>Keamanan akun</h3><label class="chk"><input type="checkbox" data-act2="twofa" ${S.user.twofa?'checked':''}> Verifikasi dua langkah (2FA)</label><p class="hint">Saat aktif, login meminta kode 6 digit tambahan (simulasi).</p>
 <div class="grid g2"><div class="card soft"><b>HTTPS / SSL</b><p class="small muted">Halaman ini dilayani lewat HTTPS.</p></div><div class="card soft"><b>Enkripsi &amp; firewall</b><p class="small muted">Di versi server: enkripsi data saat disimpan dan firewall aplikasi web.</p></div></div></div>
 <div class="card stack"><h3>Cadangan data</h3><p class="small muted">Data prototipe tersimpan di browser ini. Salin cadangan JSON untuk memindahkannya.</p><div class="row"><button class="btn" data-act="backup">${ic('copy')}Salin cadangan</button><button class="btn dng" data-act="reset">Reset ke data contoh</button></div><textarea id="bk" placeholder="Tempel cadangan JSON di sini untuk memulihkan"></textarea><button class="btn" data-act="restore" style="width:fit-content">Pulihkan</button></div>
 <div class="card stack"><h3>Anti-abuse</h3><p class="small muted">Aktif di halaman isi: CAPTCHA hitung sederhana, honeypot untuk bot, batas satu respons per perangkat (opsional), serta penandaan respons terlalu cepat atau seragam. Blacklist IP memerlukan server.</p></div>`;
 else if(T==='integrasi')b=`<div class="card stack"><h3>Integrasi pihak ketiga <span class="pill warn">simulasi</span></h3><div class="grid g2">${['Google Sheets','Zapier','Slack','Microsoft Teams','Salesforce','HubSpot','Payment gateway (survei berbayar)'].map(n=>`<label class="card soft chk" style="justify-content:space-between"><span><b>${n}</b></span><input type="checkbox" data-integ="${n}" ${S.integ[n]?'checked':''}></label>`).join('')}</div></div>
 <div class="card stack"><h3>API &amp; webhook</h3><label class="f">Endpoint webhook<input type="url" data-pref2="webhook" placeholder="https://contoh.com/hook" value="${esc(S.webhook||'')}"></label><div class="row"><button class="btn" data-act="genkey">${ic('plus')}Buat API key</button></div>${S.apiKeys.map(k=>`<div class="code row"><span style="flex:1">${k}</span><button class="btn sm" data-act="cp" data-v="${k}">Salin</button><button class="btn sm dng" data-act="rmkey" data-v="${k}">Cabut</button></div>`).join('')}
 <h4>Dokumentasi singkat</h4><div class="code">GET  /api/v1/surveys\nGET  /api/v1/surveys/{id}/responses\nPOST /api/v1/surveys/{id}/responses\nAuthorization: Bearer &lt;API_KEY&gt;</div><p class="hint">Endpoint ini rancangan untuk versi server. Prototipe belum menyediakan REST API sungguhan.</p></div>`;
 else b=`<div class="grid g3">${[['Gratis','Rp0','3 survei aktif · 100 respons/survei · ekspor CSV',1],['Pro','Rp49.000/bulan','Survei tanpa batas · logika lanjutan · laporan otomatis',0],['Institusi','Kustom','SSO · API · server sendiri',0]].map(p=>`<div class="card price ${p[3]?'hl':''}"><h3>${p[0]}${p[3]?' <span class="pill pri">paket Anda</span>':''}</h3><div class="amt">${p[1]}</div><p class="small muted">${p[2]}</p><button class="btn ${p[3]?'':'pri'}" data-act="pay" data-v="${p[0]}" ${p[3]?'disabled':''}>${p[3]?'Aktif':'Coba gratis 14 hari'}</button></div>`).join('')}</div><div class="card stack"><h3>Pembayaran &amp; invoice</h3><p class="small muted">Metode: transfer bank, e-wallet, kartu kredit. Invoice dikirim ke email akun. Pembayaran di prototipe ini hanya simulasi.</p></div>`;
 return appShell(`<div class="ph"><h2>Pengaturan</h2></div><div class="tabs">${[['tampilan','Tampilan'],['keamanan','Keamanan & data'],['integrasi','Integrasi & API'],['langganan','Langganan']].map(t=>`<button class="${T===t[0]?'on':''}" data-act="stab" data-v="${t[0]}">${t[1]}</button>`).join('')}</div>${b}`,'settings')};
PG.profile=()=>{const u=S.user;return appShell(`<div class="ph"><h2>Profil</h2></div><div class="card stack"><form data-form="profile" class="stack"><div class="grid g2"><label class="f">Nama<input type="text" name="name" value="${esc(u.name)}" required></label><label class="f">Email<input type="email" name="email" value="${esc(u.email)}" required></label></div><label class="f">Kata sandi baru<input type="password" name="pw" minlength="8" placeholder="kosongkan jika tidak diganti"></label><button class="btn pri" style="align-self:flex-start">Simpan profil</button></form></div>
 <div class="card stack"><h3>Peran akses</h3><label class="f">Peran akun (demo, untuk mencoba hak akses)${sel(Object.entries(ROLE),u.role,'id="role"')}</label><div class="tbl"><table><tr><th>Peran</th><th>Hak akses</th></tr><tr><td>Admin</td><td>Semua fitur, kelola tim dan pengaturan</td></tr><tr><td>Editor/Kreator</td><td>Buat, ubah, publikasikan survei, lihat hasil</td></tr><tr><td>Viewer/Analis</td><td>Lihat survei dan hasil saja</td></tr><tr><td>Responden</td><td>Mengisi survei lewat tautan, tanpa akun</td></tr></table></div></div>
 <div class="card stack"><h3>Data &amp; privasi</h3><p class="small muted">Anda dapat mengunduh atau menghapus seluruh data Anda kapan saja (hak subjek data menurut UU PDP dan GDPR).</p><div class="row"><button class="btn" data-act="backup">${ic('copy')}Salin data saya</button><button class="btn dng" data-act="reset">Hapus semua data</button></div></div>`,'profile')};
PG.team=()=>{const adm=S.user.role==='admin';return appShell(`<div class="ph"><h2>Tim &amp; aktivitas</h2></div>
 <div class="card stack"><h3>Anggota tim</h3><div class="tbl"><table><tr><th>Nama</th><th>Email</th><th>Peran</th><th>Status</th></tr>${S.team.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.email)}</td><td>${ROLE[t.role]}</td><td><span class="pill ${t.status==='aktif'?'ok':'warn'}">${t.status}</span></td></tr>`).join('')}</table></div>
 ${adm?`<form data-form="invite" class="row"><input type="email" name="email" placeholder="email@rekan.com" required style="max-width:260px" aria-label="Email anggota">${sel([['editor','Editor'],['viewer','Viewer']],'editor','name="role"')}<button class="btn pri">Undang</button></form>`:'<p class="hint">Hanya admin yang bisa mengundang anggota.</p>'}</div>
 <div class="card stack"><h3>Tugas kolaborasi</h3>${S.tasks.map(t=>`<label class="chk"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span style="${t.done?'text-decoration:line-through;color:var(--muted)':''}">${esc(t.text)} <span class="pill">${esc(t.who.split('@')[0])}</span></span></label>`).join('')}
 <form data-form="task" class="row"><input type="text" name="text" placeholder="Tugas baru" required style="flex:1 1 200px" aria-label="Tugas baru">${sel(S.team.map(t=>[t.email,t.name]),S.user.email,'name="who"')}<button class="btn">Tambah</button></form></div>
 <div class="card stack"><h3>Activity log</h3>${S.log.slice(0,20).map(l=>`<div class="small"><b>${esc(l.who)}</b> ${esc(l.msg)} <span class="muted tiny">· ${fdt(l.t)}</span></div>`).join('')}</div>`,'team')};

/* ----- Info ----- */
const FAQ=[['Bagaimana cara membuat survei?','Buka Survei saya, klik Survei baru, tambahkan pertanyaan dari tipe yang tersedia, lalu klik Publikasikan.'],['Apa bedanya skip logic dan tampil bersyarat?','Skip logic melompatkan responden ke pertanyaan lain setelah menjawab. Tampil bersyarat menyembunyikan sebuah pertanyaan kecuali jawaban sebelumnya memenuhi syarat.'],['Bagaimana menguji validitas dan reliabilitas?','Buka Hasil, tab Uji instrumen, lalu pilih butir Likert. Hasil memuat r hitung, r tabel, keputusan valid, dan Cronbach\'s Alpha.'],['Bagaimana mengekspor data ke SPSS?','Buka Hasil, tab Ekspor, pilih Sintaks SPSS, lalu tempel ke SPSS Syntax Editor dan jalankan.'],['Apakah jawaban responden anonim?','Ya jika opsi Anonim aktif. Jika nonaktif, nama dan email diminta di awal.'],['Mengapa data hilang ketika saya buka di perangkat lain?','Prototipe ini menyimpan data di browser. Gunakan cadangan JSON di Pengaturan untuk memindahkannya.']];
PG.help=()=>pub(`<section class="sec"><h2>Pusat bantuan</h2><input type="search" id="hq" placeholder="Cari di knowledge base" aria-label="Cari bantuan" style="max-width:420px">
<div class="grid g2"><div class="card stack"><h3>Panduan cepat</h3><ol class="small stack" style="padding-left:1.1rem;margin:0"><li>Buat survei dan atur judul, estimasi, serta pesan pembuka.</li><li>Tambahkan pertanyaan, atur logika bila perlu.</li><li>Pratinjau di ponsel dan desktop.</li><li>Publikasikan lalu bagikan tautan atau QR.</li><li>Analisis hasil dan salin laporan.</li></ol></div>
<div class="card stack"><h3>Changelog</h3><p class="small"><b>v0.9</b> · Uji validitas dan Cronbach's Alpha, laporan otomatis.</p><p class="small"><b>v0.8</b> · Piping, logika bersyarat, ekspor sintaks SPSS.</p><p class="small"><b>v0.7</b> · Dark mode, font besar, kontras tinggi.</p><p class="small muted">Tutorial video belum tersedia di prototipe ini.</p></div></div>
<div class="card" id="faqs"><h3>Pertanyaan umum (FAQ)</h3>${FAQ.map(f=>`<details class="faq"><summary>${f[0]}</summary><p class="muted" style="margin-top:.4rem">${f[1]}</p></details>`).join('')}</div>
<div class="card soft row"><span>Belum terjawab?</span><button class="btn pri" data-go="contact">Hubungi dukungan</button></div></section>`);
PG.contact=()=>pub(`<section class="sec" style="max-width:640px"><h2>Kontak &amp; dukungan</h2><div class="card stack"><form data-form="contact" class="stack"><label class="f">Nama<input type="text" name="name" required value="${esc(S.user?.name||'')}"></label><label class="f">Email<input type="email" name="email" required value="${esc(S.user?.email||'')}"></label><label class="f">Pesan<textarea name="msg" required></textarea></label><button class="btn pri" style="align-self:flex-start">Kirim tiket</button></form></div>
${S.tickets.length?`<div class="card stack"><h3>Tiket Anda</h3>${S.tickets.map(t=>`<div class="small"><b>#${t.id}</b> ${esc(t.msg.slice(0,80))} <span class="pill warn">Menunggu</span></div>`).join('')}</div>`:''}<p class="muted small">Email dukungan: dukungan@suaraku.id (contoh). Tiket di prototipe ini hanya tersimpan di browser.</p></section>`);
PG.legal=()=>{const p=R.id==='privasi';return pub(`<section class="sec"><div class="prose"><h2>${p?'Kebijakan privasi':'Syarat &amp; ketentuan'}</h2>${p?`<p>Kebijakan ini menjelaskan data apa yang dikumpulkan saat Anda memakai Suaraku Survey dan bagaimana data itu dilindungi.</p><h3>Data yang dikumpulkan</h3><p>Data akun (nama, email), isi survei, dan jawaban responden. Pada survei anonim, nama dan email responden tidak diminta. Waktu mulai, waktu selesai, dan jenis perangkat dicatat untuk kontrol kualitas.</p><h3>Persetujuan responden</h3><p>Setiap responden diminta menyetujui pernyataan persetujuan sebelum mengisi. Pembuat survei wajib menjelaskan tujuan penggunaan data.</p><h3>Anonimisasi</h3><p>Hasil dianalisis secara agregat. Pembuat survei tidak boleh mencoba mengidentifikasi responden pada survei anonim.</p><h3>Hak Anda</h3><p>Anda dapat mengakses, mengoreksi, mengekspor, dan menghapus data Anda sesuai UU Pelindungan Data Pribadi dan prinsip GDPR.</p><h3>Penyimpanan</h3><p>Versi prototipe menyimpan data di browser Anda. Versi produksi memakai HTTPS, enkripsi data, dan pencadangan otomatis.</p>`:`<p>Dengan memakai layanan ini Anda setuju pada ketentuan berikut.</p><h3>Penggunaan</h3><p>Gunakan layanan secara sah. Dilarang menyebar spam, mengumpulkan data sensitif tanpa persetujuan, atau meniru pihak lain.</p><h3>Tanggung jawab pembuat survei</h3><p>Pembuat survei bertanggung jawab atas isi survei dan penggunaan data responden.</p><h3>Ketersediaan</h3><p>Kami berupaya menjaga layanan tetap berjalan, tetapi tidak menjamin bebas gangguan.</p><h3>Perubahan</h3><p>Ketentuan dapat berubah. Perubahan penting diumumkan di changelog.</p>`}</div></section>`)};
PG['404']=()=>pub(`<section class="sec" style="text-align:center;align-items:center;padding:3rem 0"><div class="err">404</div><h2>Halaman tidak ditemukan</h2><p class="muted">Tautan mungkin salah atau survei sudah dihapus.</p><button class="btn pri" data-go="${S.user?'dashboard':'landing'}">Kembali ke beranda</button></section>`);
PG['500']=()=>pub(`<section class="sec" style="text-align:center;align-items:center;padding:3rem 0"><div class="err">500</div><h2>Terjadi kesalahan</h2><p class="muted">Sesuatu tidak berjalan semestinya. Muat ulang halaman atau kembali ke beranda.</p><div class="row"><button class="btn pri" data-act="reload">Muat ulang</button><button class="btn" data-go="landing">Beranda</button></div></section>`);
